dtsPropsFor.AccessibleDialog:
/** Whether the dialog is open */
  open: boolean;
  /** Called when the dialog should close */
  onClose: () => void;
  /** Dialog title (also used for aria-labelledby) */
  title: string;
  children: React.ReactNode;
  testId?: string;
  /** Max-width utility class (default: max-w-md) */
  maxWidth?: string;
  /** Show the close button (default: true) */
  showClose?: boolean;

dtsPropsFor.AlertDialog:
open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  description: string;
  confirmLabel?: string;
  cancelLabel?: string;
  onConfirm: () => void;
  /** destructive = red confirm, warning = gold confirm */
  variant?: "destructive" | "warning";
  isPending?: boolean;
  /** Extra controls between the description and the buttons */
  children?: React.ReactNode;
  confirmDisabled?: boolean;

dtsPropsFor.Button:
variant?: "primary" | "secondary" | "destructive" | "outline" | "ghost" | "link";
  size?: "sm" | "md" | "lg" | "icon";
  /** Render the child element instead of a <button> (Radix Slot) */
  asChild?: boolean;
  disabled?: boolean;
  type?: "button" | "submit" | "reset";
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.DropdownMenu:
/** Radix root. Compose with DropdownMenuTrigger / DropdownMenuContent /
  *  DropdownMenuItem / DropdownMenuSeparator / DropdownMenuLabel. */
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  modal?: boolean;
  children?: React.ReactNode;

dtsPropsFor.ErrorBoundary:
children: React.ReactNode;
  /** Custom fallback — receives the error and a reset callback */
  fallback?: (error: Error, reset: () => void) => React.ReactNode;
  /** Changing this value auto-resets any caught error */
  resetKey?: string;

dtsPropsFor.Input:
type?: string;
  value?: string | number;
  defaultValue?: string | number;
  placeholder?: string;
  disabled?: boolean;
  readOnly?: boolean;
  onChange?: React.ChangeEventHandler<HTMLInputElement>;
  className?: string;

dtsPropsFor.StreamBadge:
/** Whether the SSE stream is currently connected */
  connected: boolean;
  className?: string;

dtsPropsFor.UnsavedChangesDialog:
open: boolean;
  onConfirm: () => void;
  onCancel: () => void;
  /** Defaults to "You have unsaved changes…" */
  message?: string;
  /** Defaults to "Unsaved Changes" */
  title?: string;

dtsPropsFor.AgentPicker:
value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  readOnly?: boolean;

dtsPropsFor.CreateOrWizardDialog:
open: boolean;
  onClose: () => void;
  type: "agent" | "group";
  wizardPath: string;
  /** Picked "Quick Create" — close this dialog and open the create form */
  onQuickCreate: () => void;

dtsPropsFor.EmptyState:
/** Lucide icon component, e.g. `Bot` from lucide-react */
  icon: React.ComponentType<{ className?: string }>;
  title: string;
  description?: string;
  /** Omit both action props for a "no search results" empty state */
  actionLabel?: string;
  onAction?: () => void;

dtsPropsFor.ErrorState:
message: string;
  onRetry?: () => void;
  retryLabel?: string;

dtsPropsFor.InfiniteScrollSentinel:
onLoadMore: () => void;
  isFetchingMore: boolean;
  hasMore: boolean;

dtsPropsFor.RefetchErrorNotice:
onRetry: () => void;
  className?: string;
  /** Overrides the default "could not refresh" wording */
  message?: string;

dtsPropsFor.ResourceTypeBadge:
/** Resource slug. Known keys get a distinct color: agent, workflow, behavior,
   *  rules, httpcalls, apicalls, langchain, llm, output, property, propertysetter,
   *  dictionary, regulardictionary, mcpcalls, rag, snippet, snippets. Anything else
   *  renders with a neutral fallback, and a trailing ".json" is stripped. */
  type: string;

dtsPropsFor.SecretKeyPicker:
/** Plain text, or a vault reference of the form vault:<keyName> */
  value: string;
  onChange: (value: string) => void;
  readOnly?: boolean;
  tenantId?: string;
  placeholder?: string;
  testId?: string;
